import { sql } from 'drizzle-orm';
import {
  bigint,
  customType,
  doublePrecision,
  timestamp,
  uuid,
} from 'drizzle-orm/pg-core';

/** UUID v4 primary key generated by Postgres (gen_random_uuid). */
export const pk = () => uuid('id').primaryKey().defaultRandom();

/** timestamptz – all timestamps are stored in UTC. */
export const tstz = (name: string) => timestamp(name, { withTimezone: true });

export const createdAt = () => tstz('created_at').notNull().defaultNow();
export const updatedAt = () =>
  tstz('updated_at')
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());
export const deletedAt = () => tstz('deleted_at');

/** Money: integer centimes of DZD. bigint read as JS number (safe < 2^53). */
export const money = (name: string) => bigint(name, { mode: 'number' });

export const latitude = () => doublePrecision('latitude');
export const longitude = () => doublePrecision('longitude');

const geographyPoint = customType<{ data: string; driverData: string }>({
  dataType: () => 'geography',
});

/**
 * PostGIS point derived from latitude/longitude (read-only, generated by the DB).
 * Used for radius searches with a GiST index.
 */
export const location = () =>
  geographyPoint('location').generatedAlwaysAs(
    sql`CASE WHEN latitude IS NOT NULL AND longitude IS NOT NULL THEN ST_SetSRID(ST_MakePoint(longitude, latitude), 4326)::geography END`,
  );
